    """Restore the triangularly displaced cyclic pattern from row zero.

    The reference row contains the undisturbed sequence. On every later row,
    positions before that row's diagonal come from the next reference column;
    the diagonal and positions after it retain their reference-column values.
    """
    h, w = len(grid), len(grid[0])
    out = [list(grid[0])]
    for r in range(1, h):
